        Ok(await editor.OpenAsync(Path.Combine(root,".local/fixtures/surface-brush",file),decision:DirtyDecision.Discard));Refresh();await Workspace(4);Click(Named<Button>("ViewTopButton"));await Workspace(3);
    }
    private static async Task BrushWorld(params Vec3[] points)
    {
        await Idle();Assert((bool)Invoke("BeginBrushStroke",ProjectMeasuredWorld(points[0]))!,"Brush gesture did not begin: "+Named<TextBlock>("Status").Text);
        foreach(var point in points.Skip(1))Invoke("ExtendBrushStroke",ProjectMeasuredWorld(point));
        await (Task)Invoke("EndBrushStroke",ProjectMeasuredWorld(points[^1]))!;await Idle();
    }
    private static SurfaceBrushRequest BrushRequest()=>editor.Snapshot.Preview?.Request as SurfaceBrushRequest??throw new InvalidOperationException("Brush preview missing: "+Named<TextBlock>("Status").Text);
